134			{"empty instance id", "svc", 0, []Instance{{ID: "  ", Address: "h:1"}}},
135			{"duplicate ids", "svc", 0, []Instance{{ID: "a", Address: "h:1"}, {ID: "a", Address: "h:2"}}},
136			{"empty address", "svc", 0, []Instance{{ID: "a", Address: "  "}}},
137			{"missing port", "svc", 0, []Instance{{ID: "a", Address: "host"}}},
138			{"empty host", "svc", 0, []Instance{{ID: "a", Address: ":8080"}}},
139			{"non-numeric port", "svc", 0, []Instance{{ID: "a", Address: "host:http"}}},
140			{"port zero", "svc", 0, []Instance{{ID: "a", Address: "host:0"}}},
141			{"port too high", "svc", 0, []Instance{{ID: "a", Address: "host:65536"}}},
142			{"port with sign", "svc", 0, []Instance{{ID: "a", Address: "host:+80"}}},
143			{"port with spaces", "svc", 0, []Instance{{ID: "a", Address: "host: 80"}}},
144			{"unbracketed ipv6", "svc", 0, []Instance{{ID: "a", Address: "::1:8080"}}},
145			{"bad bracketed ipv6", "svc", 0, []Instance{{ID: "a", Address: "[zzzz]:8080"}}},
146			{"bracketed without port", "svc", 0, []Instance{{ID: "a", Address: "[::1]"}}},
147			{"bad domain char", "svc", 0, []Instance{{ID: "a", Address: "my_host:80"}}},
148		}
149		for _, tc := range cases {
150			t.Run(tc.name, func(t *testing.T) {
151				if _, err := r.ValidateRegistration(tc.service, tc.revision, tc.instances); err == nil {
152					t.Fatalf("expected validation error")
153				}
154			})
155		}
156	
157		// Whitespace is trimmed and valid addresses are accepted.
158		reg, err := r.ValidateRegistration("  svc  ", 0, []Instance{
159			{ID: "  a  ", Address: "  host.example:8080  "},
160			{ID: "b", Address: "127.0.0.1:443"},
161			{ID: "c", Address: "[::1]:8080"},
162		})
163		if err != nil {
164			t.Fatalf("valid addresses rejected: %v", err)
