170		// A failed validation must not consume a revision or create a service.
171		if _, err := r.ValidateRegistration("svc", 0, []Instance{{ID: "a", Address: "bad"}}); err == nil {
172			t.Fatalf("expected error")
173		}
174		if rev := r.RevisionOf("svc"); rev != 0 {
175			t.Fatalf("revision consumed: %d", rev)
176		}
177	}
